 private volatile JSONObject remoteConfig=new JSONObject(); private volatile boolean checkingRemote=false; private int ink=Color.rgb(32,54,52),teal=Color.rgb(40,125,114),bg=Color.rgb(244,247,246); private SharedPreferences prefs;private LinearLayout root;private String lang="fa";private boolean onHome=true;private int cardIndex=0;private final int[][] cardColors={{225,244,239},{230,239,252},{250,238,220},{243,232,250},{255,235,231},{230,244,249},{240,243,226},{246,237,228}};
 private String t(String k){JSONObject all=remoteConfig.optJSONObject("translations");JSONObject byLang=all==null?null:all.optJSONObject(lang);String override=byLang==null?"":byLang.optString(k,"");if(override!=null&&!override.trim().isEmpty())return override;int i=Arrays.asList(KEY).indexOf(k);return i<0?k:TR[Arrays.asList(LANG).indexOf(lang)][i];}
 private boolean rtl(){return lang.equals("fa")||lang.equals("ar");}
 private GradientDrawable shape(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(r);return d;}
 private TextView txt(String s,int z,int c,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);if(bold)v.setTypeface(null,1);v.setGravity(rtl()?Gravity.RIGHT:Gravity.LEFT);v.setTextDirection(rtl()?View.TEXT_DIRECTION_RTL:View.TEXT_DIRECTION_LTR);return v;}
 private LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setLayoutDirection(rtl()?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);return l;}
 private void start(String title,String sub){onHome=title.equals(t("home"));cardIndex=0;ScrollView sc=new ScrollView(this);sc.setBackgroundColor(bg);root=col();root.setPadding(18,18,18,28);sc.addView(root);setContentView(sc);if(!onHome){TextView back=txt("↩  "+t("back"),15,teal,true);back.setPadding(12,10,12,10);back.setBackground(shape(Color.WHITE,14));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.bottomMargin=12;root.addView(back,bp);back.setOnClickListener(v->home());}LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setOrientation(0);TextView brand=txt(t("brand"),25,ink,true);top.addView(brand,new LinearLayout.LayoutParams(0,-2,1));TextView language=txt("🌐 "+t("language"),13,teal,true);language.setPadding(10,8,10,8);language.setOnClickListener(v->chooseLanguage());top.addView(language);root.addView(top);TextView s=txt(t("tagline")+" · "+sub,13,Color.GRAY,false);s.setPadding(0,5,0,14);root.addView(s);TextView h=txt(title,20,Color.WHITE,true);h.setPadding(16,15,16,15);h.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.rgb(35,112,105),Color.rgb(68,157,139)}));h.setElevation(3);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,-2);hp.bottomMargin=16;root.addView(h,hp);}
 private void card(String h,String d,Runnable r){int[] colors=cardColors[cardIndex++%cardColors.length];int base=Color.rgb(colors[0],colors[1],colors[2]);int end=Color.rgb(Math.min(255,colors[0]+8),Math.min(255,colors[1]+8),Math.min(255,colors[2]+8));LinearLayout c=col();c.setPadding(17,16,17,16);GradientDrawable gd=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{base,end});gd.setCornerRadius(20);gd.setStroke(1,Color.argb(35,30,70,70));c.setBackground(gd);c.setElevation(2);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=11;root.addView(c,p);c.addView(txt(h,17,ink,true));TextView v=txt(d,13,Color.rgb(78,94,91),false);v.setPadding(0,6,0,0);c.addView(v);if(r!=null)c.setOnClickListener(vw->r.run());}
 private EditText field(String hint){EditText e=new EditText(this);e.setSingleLine();e.setHint(hint);e.setTextSize(15);e.setGravity(rtl()?Gravity.RIGHT:Gravity.LEFT);e.setBackground(shape(Color.WHITE,12));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=9;root.addView(e,p);return e;}
