 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("hamrah_yar",0);lang=prefs.getString("language","fa");if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},77);applyDirection();home();checkRemoteUpdates(false);}
 private void applyDirection(){getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);getWindow().getDecorView().setLayoutDirection(rtl()?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);}
 private String remoteMessage(){JSONObject messages=remoteConfig.optJSONObject("message");return messages==null?"":messages.optString(lang,"");}
 private void checkRemoteUpdates(boolean showResult){if(checkingRemote){if(showResult)Toast.makeText(this,L("در حال بررسی است…","Checking…","جارٍ التحقق…","Wird geprüft…"),Toast.LENGTH_SHORT).show();return;}checkingRemote=true;new Thread(()->{JSONObject payload=null;String failure=null;HttpURLConnection connection=null;try{URL url=new URL("https://raw.githubusercontent.com/jakshilton-ai/hamrah-yar/main/remote-config.json?ts="+System.currentTimeMillis());connection=(HttpURLConnection)url.openConnection();connection.setConnectTimeout(8000);connection.setReadTimeout(8000);connection.setRequestMethod("GET");connection.setRequestProperty("Cache-Control","no-cache");int status=connection.getResponseCode();if(status!=200)throw new IOException("HTTP "+status);ByteArrayOutputStream out=new ByteArrayOutputStream();InputStream in=connection.getInputStream();byte[] buffer=new byte[4096];int count;while((count=in.read(buffer))!=-1)out.write(buffer,0,count);in.close();payload=new JSONObject(out.toString("UTF-8"));}catch(Exception e){failure=e.getMessage();}finally{if(connection!=null)connection.disconnect();}final JSONObject result=payload;final String error=failure;runOnUiThread(()->{checkingRemote=false;if(result!=null){remoteConfig=result;if(onHome)home();if(showResult)Toast.makeText(this,L("تغییرات آنلاین دریافت شد.","Online updates received.","تم استلام التحديثات.","Online-Updates empfangen."),Toast.LENGTH_LONG).show();}else if(showResult){Toast.makeText(this,L("اتصال برقرار نشد؛ بعداً دوباره تلاش کن.","Could not connect. Try again later.","تعذر الاتصال. حاول لاحقاً.","Verbindung fehlgeschlagen. Bitte später erneut versuchen."),Toast.LENGTH_LONG).show();}});}).start();}
 private void chooseLanguage(){String[] names={"فارسی","English","العربية","Deutsch"};new AlertDialog.Builder(this).setTitle(t("chooseLang")).setSingleChoiceItems(names,Arrays.asList(LANG).indexOf(lang),(d,w)->{lang=LANG[w];prefs.edit().putString("language",lang).apply();d.dismiss();applyDirection();home();Toast.makeText(this,t("languageChanged"),Toast.LENGTH_SHORT).show();}).setNegativeButton(t("cancel"),null).show();}
 private String two(int n){return n<10?"0"+n:""+n;} private String ascii(String v){StringBuilder b=new StringBuilder();for(int i=0;i<v.length();i++){char c=v.charAt(i);if(c>='۰'&&c<='۹')c=(char)('0'+c-'۰');else if(c>='٠'&&c<='٩')c=(char)('0'+c-'٠');if(c==',')c='.';b.append(c);}return b.toString();} private int num(String v){return Integer.parseInt(ascii(v).trim());}
 private int[] jalali(int gy,int gm,int gd){Calendar check=Calendar.getInstance();check.clear();check.setLenient(false);check.set(gy,gm-1,gd);check.getTime();int[] gdm={0,31,59,90,120,151,181,212,243,273,304,334};if(gm<1||gm>12||gd<1||gd>31)throw new IllegalArgumentException();int y=gy-1600,m=gm-1,d=gd-1;int g=y*365+(y+3)/4-(y+99)/100+(y+399)/400+gdm[m]+d;if(m>1&&((gy%4==0&&gy%100!=0)||gy%400==0))g++;int j=g-79,np=j/12053;j%=12053;int jy=979+33*np+4*(j/1461);j%=1461;if(j>=366){jy+=(j-1)/365;j=(j-1)%365;}int jm,jd;if(j<186){jm=1+j/31;jd=1+j%31;}else{jm=7+(j-186)/30;jd=1+(j-186)%30;}return new int[]{jy,jm,jd};}
 private void home(){Calendar c=Calendar.getInstance();int[] j=jalali(c.get(1),c.get(2)+1,c.get(5));start(t("home"),"");card(t("today")+" · "+j[0]+"/"+two(j[1])+"/"+two(j[2]),t("gregorian")+": "+c.get(1)+"/"+two(c.get(2)+1)+"/"+two(c.get(5)),this::calendar);card(t("calendar"),t("calendarDesc"),this::calendar);card(t("health"),t("healthDesc"),this::health);card(t("reminders"),t("reminderDesc"),this::reminders);card(t("finance"),t("financeDesc"),this::finance);card(t("education"),t("educationDesc"),this::education);card(t("maps"),t("mapsDesc"),()->records(t("maps"),"routes",L("مسیرها و مکان‌های ذخیره‌شده","Saved routes and places","المسارات والأماكن المحفوظة","Gespeicherte Routen und Orte")));card(t("places"),t("placesDesc"),()->records(t("places"),"directory",L("نام مرکز، نشانی و تلفن را ثبت کن","Save a place, address and phone","سجّل المكان والعنوان والهاتف","Ort, Adresse und Telefon speichern")));card(t("profile"),L("محاسبه سن بر اساس تاریخ تولد","Calculate age from date of birth","احسب العمر من تاريخ الميلاد","Alter anhand des Geburtsdatums berechnen"),this::profile);card(t("documents"),L("مدارک، بیمه و تاریخ انقضا","Documents, insurance and expiry dates","المستندات والتأمين وتواريخ الانتهاء","Dokumente, Versicherungen und Ablaufdaten"),()->records(t("documents"),"documents",L("عنوان مدرک و تاریخ انقضا","Document name and expiry date","اسم المستند وتاريخ الانتهاء","Dokumentname und Ablaufdatum")));card(t("homeCar"),L("سرویس‌ها و تعمیرات خانه و خودرو","Home and vehicle maintenance log","سجل صيانة المنزل والسيارة","Wartungsprotokoll für Haus und Fahrzeug"),()->records(t("homeCar"),"maintenance",L("نوع سرویس، تاریخ و هزینه","Service, date and cost","نوع الصيانة والتاريخ والتكلفة","Service, Datum und Kosten")));card(t("travel"),L("چک‌لیست سفر و یادداشت‌ها","Travel checklist and notes","قائمة السفر والملاحظات","Reise-Checkliste und Notizen"),()->records(t("travel"),"travel",L("وسیله، رزرو یا یادداشت سفر","Item, booking or travel note","عنصر أو حجز أو ملاحظة سفر","Gegenstand, Buchung oder Reisenotiz")));String remoteMessage=remoteMessage();if(!remoteMessage.isEmpty())card(L("پیام و تغییرات جدید","New updates","تحديثات جديدة","Neue Updates"),remoteMessage,null);card(L("بررسی تغییرات آنلاین","Check online updates","التحقق من التحديثات","Online-Updates prüfen"),L("متن‌ها و پیام‌های برنامه بدون نصب مجدد به‌روزرسانی می‌شوند.","App text and announcements update without reinstalling.","يتم تحديث النصوص والإعلانات دون إعادة التثبيت.","Texte und Hinweise werden ohne Neuinstallation aktualisiert."),()->checkRemoteUpdates(true));}
 private void calendar(){start(t("calendar"),t("calendarDesc"));EditText y=field(t("year")),m=field(t("month")),d=field(t("day"));TextView out=txt(t("convertResult"),16,teal,true);root.addView(out);btn(t("convert"),()->{try{int[] a=jalali(Integer.parseInt(y.getText().toString()),Integer.parseInt(m.getText().toString()),Integer.parseInt(d.getText().toString()));out.setText(" "+a[0]+"/"+two(a[1])+"/"+two(a[2]));}catch(Exception e){out.setText(t("invalidDate"));}});card(t("calendar"),t("calendarNext"),null);nav();}
 private void health(){start(t("healthTitle"),t("bmiNote"));EditText h=field(t("height")),w=field(t("weight"));TextView out=txt(t("bmiResult"),16,teal,true);root.addView(out);btn(t("calcBmi"),()->{try{double a=Double.parseDouble(ascii(h.getText().toString()))/100,b=Double.parseDouble(ascii(w.getText().toString()));if(a<=0||b<=0)throw new Exception();double v=b/(a*a);String cat=v<18.5?t("bmiUnder"):v<25?t("bmiNormal"):v<30?t("bmiOver"):t("bmiHigh");out.setText(String.format(Locale.US,"BMI: %.1f · %s",v,cat));}catch(Exception e){out.setText(t("invalidDate"));}});card(t("health"),t("healthPrivacy"),null);nav();}
 private void reminders(){start(t("reminderTitle"),t("reminderSub"));LinearLayout list=col();root.addView(list);Set<String> set=new HashSet<>(prefs.getStringSet("items",new HashSet<String>()));for(String item:new ArrayList<>(set)){TextView v=txt("• "+item,15,ink,false);v.setPadding(8,12,8,12);list.addView(v);v.setOnLongClickListener(x->{Set<String> n=new HashSet<>(prefs.getStringSet("items",new HashSet<String>()));n.remove(item);prefs.edit().putStringSet("items",n).apply();reminders();return true;});}btn(t("addReminder"),()->{EditText e=new EditText(this);e.setHint(t("reminderHint"));new AlertDialog.Builder(this).setTitle(t("addReminder")).setView(e).setNegativeButton(t("cancel"),null).setPositiveButton(t("save"),(x,y)->{String title=e.getText().toString().trim();if(!title.isEmpty()){Calendar when=Calendar.getInstance();new DatePickerDialog(this,(dp,yy,mm,dd)->{when.set(yy,mm,dd);new TimePickerDialog(this,(tp,hh,mi)->{when.set(Calendar.HOUR_OF_DAY,hh);when.set(Calendar.MINUTE,mi);when.set(Calendar.SECOND,0);if(when.getTimeInMillis()<=System.currentTimeMillis()){Toast.makeText(this,L("زمان باید در آینده باشد","Choose a future time","اختر وقتاً في المستقبل","Wähle eine zukünftige Zeit"),Toast.LENGTH_SHORT).show();return;}String saved=title+" · "+new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US).format(when.getTime());scheduleReminder(title,when.getTimeInMillis());Set<String> n=new HashSet<>(prefs.getStringSet("items",new HashSet<String>()));n.add(saved);prefs.edit().putStringSet("items",n).apply();reminders();},when.get(Calendar.HOUR_OF_DAY),when.get(Calendar.MINUTE),true).show();},when.get(Calendar.YEAR),when.get(Calendar.MONTH),when.get(Calendar.DAY_OF_MONTH)).show();}}).show();});card(t("reminders"),L("برای حذف یادآور، آن را چند لحظه لمس کن. اعلان در زمان انتخابی ارسال می‌شود؛ مجوز اعلان گوشی باید روشن باشد.","Long-press to delete. A notification is scheduled; notification permission must be enabled.","اضغط مطولاً للحذف. يتم جدولة إشعار ويجب السماح بإشعارات التطبيق.","Zum Löschen lange drücken. Eine Benachrichtigung wird geplant; die Berechtigung muss aktiv sein."),null);nav();}
 private void scheduleReminder(String title,long at){int id=(title+at).hashCode();Intent i=new Intent(this,ReminderReceiver.class);i.putExtra("title",title);PendingIntent pi=PendingIntent.getBroadcast(this,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager am=(AlarmManager)getSystemService(ALARM_SERVICE);if(am!=null){if(Build.VERSION.SDK_INT>=23)am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pi);else am.set(AlarmManager.RTC_WAKEUP,at,pi);}}

 private String L(String fa,String en,String ar,String de){if(lang.equals("en"))return en;if(lang.equals("ar"))return ar;if(lang.equals("de"))return de;return fa;}
 private void records(String title,String key,String hint){start(title,L("ذخیره‌سازی فقط روی همین گوشی انجام می‌شود.","Data is stored only on this device.","يتم حفظ البيانات على هذا الجهاز فقط.","Daten werden nur auf diesem Gerät gespeichert."));Set<String> set=new HashSet<>(prefs.getStringSet(key,new HashSet<String>()));LinearLayout list=col();root.addView(list);for(String item:new ArrayList<>(set)){TextView v=txt("• "+item,15,ink,false);v.setPadding(8,12,8,12);list.addView(v);v.setOnLongClickListener(x->{Set<String> n=new HashSet<>(prefs.getStringSet(key,new HashSet<String>()));n.remove(item);prefs.edit().putStringSet(key,n).apply();records(title,key,hint);return true;});}btn(L("افزودن مورد","Add item","إضافة عنصر","Eintrag hinzufügen"),()->{EditText e=new EditText(this);e.setHint(hint);new AlertDialog.Builder(this).setTitle(L("ثبت اطلاعات","Save information","حفظ المعلومات","Information speichern")).setView(e).setNegativeButton(t("cancel"),null).setPositiveButton(t("save"),(d,w)->{String value=e.getText().toString().trim();if(!value.isEmpty()){Set<String> n=new HashSet<>(prefs.getStringSet(key,new HashSet<String>()));n.add(value);prefs.edit().putStringSet(key,n).apply();records(title,key,hint);}}).show();});TextView note=txt(L("برای حذف هر مورد، آن را چند لحظه لمس کن.","Long-press an item to delete it.","اضغط مطولاً على العنصر لحذفه.","Eintrag lange drücken, um ihn zu löschen."),12,Color.GRAY,false);root.addView(note);nav();}
 private void finance(){start(t("finance"),L("ثبت هزینه‌های شخصی و جمع مبالغ","Track expenses and total amounts","تسجيل المصروفات وإجمالي المبالغ","Ausgaben erfassen und summieren"));EditText amount=field(L("مبلغ به عدد","Amount","المبلغ","Betrag"));amount.setInputType(2);EditText note=field(L("شرح هزینه","Expense description","وصف المصروف","Ausgabenbeschreibung"));Set<String> set=new HashSet<>(prefs.getStringSet("expenses",new HashSet<String>()));double total=0;LinearLayout list=col();root.addView(list);for(String item:new ArrayList<>(set)){String[] a=item.split("\\|",2);try{total+=Double.parseDouble(a[0]);}catch(Exception ignored){}TextView v=txt("• "+(a.length>1?a[1]:"—")+" · "+a[0],15,ink,false);v.setPadding(8,10,8,10);list.addView(v);v.setOnLongClickListener(x->{Set<String> n=new HashSet<>(prefs.getStringSet("expenses",new HashSet<String>()));n.remove(item);prefs.edit().putStringSet("expenses",n).apply();finance();return true;});}TextView sum=txt(L("جمع هزینه‌های ثبت‌شده: ","Recorded expenses total: ","إجمالي المصروفات المسجلة: ","Summe der erfassten Ausgaben: ")+String.format(Locale.US,"%.0f",total),16,teal,true);root.addView(sum,0);btn(L("ثبت هزینه","Save expense","حفظ المصروف","Ausgabe speichern"),()->{try{double v=Double.parseDouble(ascii(amount.getText().toString()).trim());String desc=note.getText().toString().trim();if(v<=0||desc.isEmpty())throw new Exception();Set<String> n=new HashSet<>(prefs.getStringSet("expenses",new HashSet<String>()));n.add(String.format(Locale.US,"%.0f",v)+"|"+desc);prefs.edit().putStringSet("expenses",n).apply();finance();}catch(Exception e){Toast.makeText(this,L("مبلغ و شرح معتبر وارد کن","Enter a valid amount and description","أدخل مبلغاً ووصفاً صحيحاً","Gültigen Betrag und Beschreibung eingeben"),Toast.LENGTH_SHORT).show();}});card(t("finance"),L("این بخش دفتر ثبت شخصی است؛ پرداخت بانکی یا قبض آنلاین انجام نمی‌دهد.","This is a personal ledger; it does not make bank or bill payments.","هذا سجل شخصي ولا ينفذ مدفوعات بنكية أو فواتير عبر الإنترنت.","Dies ist ein persönliches Kassenbuch und führt keine Bank- oder Rechnungszahlungen aus."),null);nav();}
 private void education(){records(t("education"),"study_tasks",L("درس، تکلیف یا تاریخ امتحان","Subject, assignment or exam date","المادة أو الواجب أو موعد الامتحان","Fach, Aufgabe oder Prüfungstermin"));}
 private void profile(){start(t("profile"),L("تاریخ تولد را وارد کن","Enter your date of birth","أدخل تاريخ ميلادك","Geburtsdatum eingeben"));EditText y=field(L("سال میلادی تولد","Birth year (Gregorian)","سنة الميلاد","Geburtsjahr"));y.setInputType(2);EditText m=field(L("ماه تولد (۱ تا ۱۲)","Birth month (1–12)","شهر الميلاد","Geburtsmonat"));m.setInputType(2);EditText d=field(L("روز تولد","Birth day","يوم الميلاد","Geburtstag"));d.setInputType(2);TextView out=txt("",17,teal,true);root.addView(out);btn(L("محاسبه سن","Calculate age","احسب العمر","Alter berechnen"),()->{try{Calendar birth=Calendar.getInstance();birth.clear();birth.setLenient(false);birth.set(num(y.getText().toString()),num(m.getText().toString())-1,num(d.getText().toString()));birth.getTime();Calendar now=Calendar.getInstance();if(birth.after(now)||birth.get(Calendar.YEAR)<1900)throw new Exception();int years=now.get(Calendar.YEAR)-birth.get(Calendar.YEAR);int months=now.get(Calendar.MONTH)-birth.get(Calendar.MONTH);int days=now.get(Calendar.DAY_OF_MONTH)-birth.get(Calendar.DAY_OF_MONTH);if(days<0){months--;Calendar tmp=(Calendar)now.clone();tmp.add(Calendar.MONTH,-1);days+=tmp.getActualMaximum(Calendar.DAY_OF_MONTH);}if(months<0){years--;months+=12;}out.setText(L("سن: ","Age: ","العمر: ","Alter: ")+years+L(" سال و "," years, "," سنة و "," Jahre und ")+months+L(" ماه و "," months and "," شهر و "," Monate und ")+days+L(" روز"," days"," يوم"," Tage"));}catch(Exception e){out.setText(t("invalidDate"));}});card(t("profile"),L("تاریخ تولد فقط برای محاسبه در همین صفحه استفاده می‌شود و ذخیره نمی‌شود.","Birth date is used only for this calculation and is not saved.","يُستخدم تاريخ الميلاد لهذا الحساب فقط ولا يتم حفظه.","Das Geburtsdatum wird nur für diese Berechnung verwendet und nicht gespeichert."),null);nav();}
 @Override public void onBackPressed(){if(!onHome){home();}else{super.onBackPressed();}}
